css:
.container {
  --current-color: #0ff;
  --bg-size: 96px;
  height: 100%;
  width: 100%;
  display: flex;
  background-image: repeating-conic-gradient(
      from 0deg at 0% 0%,
      #000 0deg,
      var(--current-color) 10deg
    ),
    repeating-conic-gradient(
      from 0deg at 100% 0%,
      var(--current-color) 0deg,
      #000 10deg
    ),
    repeating-conic-gradient(
      from 0deg at 100% 100%,
      var(--current-color) 0deg,
      #000 10deg
    ),
    repeating-conic-gradient(
      from 0deg at 0% 100%,
      var(--current-color) 0deg,
      #000 10deg
    );
  background-size: var(--bg-size) var(--bg-size);
  background-blend-mode: screen;
}
